#!/usr/bin/env python3
from __future__ import annotations
from pathlib import Path
import argparse, base64, hashlib, subprocess

EXPECTED_BRANCH="science/universal-generative-validation-v1"
EXPECTED_HEAD="84e4338ac7b112e9f0fd1844748176a2388ddc8d"
PAYLOAD={'validation/engineered/jsonutil.py': '', 'validation/engineered/ledger.py': '', 'validation/engineered/production.py': '', 'validation/engineered/metamorphic.py': '', 'validation/engineered/mutants.py': '', 'validation/engineered/mutation_score.py': '', 'validation/engineered/high_precision.py': '', 'validation/engineered/harness.py': '', 'tests/test_engineered_oracle_firewall.py': '', 'tests/test_engineered_metamorphic.py': '', 'tests/test_engineered_high_precision_conditioning.py': '', 'tests/test_engineered_cofactor_ptmc_rankone.py': '', 'tests/test_engineered_ct_generalized_vs_whitened.py': '', 'tests/test_engineered_metric_sqrt_stability.py': '', 'tests/test_engineered_framework_integrity.py': '', 'tools/run_engineered_falsification_v2.py': ''}
FROZEN=(
    "src/cualni_cryst/ct.py",
    "src/cualni_cryst/correspondence.py",
    "src/cualni_cryst/lattice.py",
    "src/cualni_cryst/stretch.py",
    "src/cualni_cryst/ball_james.py",
    "src/cualni_cryst/rank_one.py",
    "src/cualni_cryst/cofactor.py",
    "src/cualni_cryst/ptmc.py",
    "src/cualni_cryst/representation.py",
    "src/cualni_cryst/scientific_contracts.py",
    "src/cualni_cryst/project_io.py",
    "src/cualni_cryst/calculation_service.py",
)

def git(repo,*args,check=True):
    p=subprocess.run(["git","-C",str(repo),*args],text=True,stdout=subprocess.PIPE,stderr=subprocess.PIPE)
    if check and p.returncode:
        raise RuntimeError("git "+" ".join(args)+"\n"+p.stdout+p.stderr)
    return p

def main():
    ap=argparse.ArgumentParser()
    ap.add_argument("--repo",required=True)
    args=ap.parse_args()
    repo=Path(args.repo).resolve()

    branch=git(repo,"branch","--show-current").stdout.strip()
    head=git(repo,"rev-parse","HEAD").stdout.strip()
    print("branch:",branch)
    print("HEAD:  ",head)
    if branch!=EXPECTED_BRANCH:
        raise RuntimeError(f"wrong branch: {branch}")
    if head!=EXPECTED_HEAD:
        raise RuntimeError(f"wrong HEAD: {head}")

    print("\n=== PRODUCTION CORE MUST STILL BE FROZEN ===")
    for rel in FROZEN:
        p=repo/rel
        if not p.exists():
            raise RuntimeError("missing production file: "+rel)
        if git(repo,"diff","--quiet","HEAD","--",rel,check=False).returncode:
            raise RuntimeError("production core modified; refusing framework repair: "+rel)
        print("clean:",rel,hashlib.sha256(p.read_bytes()).hexdigest())

    print("\n=== REPAIR / DEEPEN FRAMEWORK ===")
    for rel,b64 in PAYLOAD.items():
        content=base64.b64decode(b64).decode("utf-8")
        compile(content,rel,"exec") if rel.endswith(".py") else None
        p=repo/rel
        p.parent.mkdir(parents=True,exist_ok=True)
        p.write_text(content,encoding="utf-8")
        print("installed:",rel)

    print("\nFramework defects fixed:")
    print("- JSON serialization handles numpy scalars/arrays")
    print("- oracle firewall no longer scans its own forbidden-token table")
    print("- runner hashes untracked source too")
    print("- harness collects many failures instead of stopping at first")
    print("- metamorphic failures now include covariance/classification diagnostics")
    print("- high-precision conditioning sweep distinguishes forward/backward error")
    print("- Mallard branches individually checked")
    print("- mutation score expanded")
    print("- generalized-pencil vs whitened-CMC differential test added")
    print("- metric sqrt/whitener stability test added")
    print("- framework self-integrity tests added")
    print("\nProduction science changed: NO")
    print("\nNEXT:")
    print("python tools/run_engineered_falsification_v2.py --profile full")

if __name__=="__main__":
    main()
